{
  "$schema": "https://wpl.dev/schemas/wpl/v1.schema.json",
  "version": "1.6.0",
  "plan": {
    "id": "l4l5-recon-2wk",
    "name": "L4-L5 Post-Herniation Reconditioning — 2-Week Starter Block",
    "description": "A conservative 2-week introductory strength block for a 42-year-old male with a resolved L4-L5 disc herniation. No heavy spinal loading; no loaded spinal flexion. Focuses on hip-hinge patterning, anti-flexion core stability, horizontal push/pull, and single-leg work. Designed to precede a full 12-week programme once tolerance is confirmed.",
    "type": "workout",
    "visibility": "template",
    "metadata": {
      "created_at": "2025-01-01T00:00:00Z",
      "updated_at": "2025-01-01T00:00:00Z",
      "created_by": "trainer",
      "tags": ["back-rehab", "reconditioning", "strength", "low-spinal-load", "beginner-return"],
      "difficulty": "beginner",
      "estimated_duration_days": 14,
      "language": "en"
    },
    "goals": [
      {
        "id": "goal-movement-quality",
        "type": "primary",
        "category": "movement_quality",
        "name": "Re-establish safe movement patterns",
        "description": "Groove hip-hinge, squat, and anti-flexion core patterns with zero pain provocation."
      },
      {
        "id": "goal-strength-base",
        "type": "secondary",
        "category": "strength",
        "name": "Build foundational strength",
        "description": "Develop moderate lower and upper body strength within spinal-safe loading parameters."
      }
    ],
    "requirements": {
      "min_age": 18,
      "fitness_level": ["beginner", "intermediate"],
      "equipment": [
        { "id": "eq-barbell", "name": "Barbell", "required": false, "alternatives": ["dumbbells"] },
        { "id": "eq-dumbbells", "name": "Dumbbells", "required": true },
        { "id": "eq-cable", "name": "Cable machine", "required": true },
        { "id": "eq-bench", "name": "Flat bench", "required": true },
        { "id": "eq-pulldown", "name": "Lat pulldown machine", "required": true },
        { "id": "eq-mat", "name": "Exercise mat", "required": true }
      ],
      "contraindications": [
        {
          "condition": "icd10:M51.1",
          "severity": "moderate",
          "action": "modify",
          "affected_activities": ["any_loaded_spinal_flexion", "heavy_deadlift", "back_squat_heavy"]
        },
        {
          "condition": "lower_back_injury",
          "severity": "moderate",
          "action": "exclude",
          "affected_activities": ["loaded_spinal_flexion", "sit_ups", "leg_press_deep_lumbar_flexion"]
        }
      ],
      "time_commitment": {
        "min_days_per_week": 3,
        "max_days_per_week": 3,
        "min_minutes_per_day": 45,
        "max_minutes_per_day": 60
      }
    },
    "athlete_thresholds": {
      "body_weight_kg": 85
    },
    "phases": [
      {
        "id": "phase-1-intro",
        "name": "Phase 1 — Movement Foundations",
        "order": 1,
        "type": "accumulation",
        "description": "Two weeks of low-load, high-quality movement. RPE capped at 6/10. Emphasis on technique, bracing, and pain-free range of motion. Three sessions per week on non-consecutive days.",
        "duration": { "value": 2, "unit": "weeks" },
        "weeks": [
          {
            "id": "week-1",
            "name": "Week 1 — Pattern Acquisition",
            "order": 1,
            "is_deload": false,
