              {
                "id": "w1d1",
                "day_of_week": 1,
                "type": "training",
                "name": "Session A — Lower Body & Core",
                "estimated_duration_minutes": 55,
                "blocks": [
                  {
                    "id": "w1d1-warmup",
                    "type": "warmup",
                    "order": 1,
                    "structure": "straight_sets",
                    "activities": [
                      {
                        "id": "w1d1-wu1",
                        "type": "simple",
                        "name": "5-min low-intensity bike or walk",
                        "duration": { "value": 5, "unit": "minutes" }
                      },
                      {
                        "id": "w1d1-wu2",
                        "type": "recovery",
                        "name": "Hip Mobility & Glute Activation",
                        "category": "mobility",
                        "prescription": {
                          "duration": { "value": 8, "unit": "minutes" },
